from pathlib import Path
import json,requests,re,sqlite3
out=Path('/home/user/workspace/calendar/out')
a=json.loads((out/'calendar_b_audit.json').read_text())
ics=(out/'calendar_export_b.ics').read_text().splitlines()
calendar=requests.get('http://127.0.0.1:18110/calendar').text.splitlines()
want={'TS-201':('20261202T140000Z','20261202T150000Z','Product certification workshop','CEDAR','training@example.invalid'), 'TS-203':('20261203T083000Z','20261203T093000Z','Support readiness clinic','ATLAS','support@example.invalid'), 'TS-207':('20261205T151500Z','20261205T164500Z','Weekend escalation drill','MAPLE','response@example.invalid')}
def parse(lines):
 result={}
 for i,x in enumerate(lines):
  if x=='BEGIN:VEVENT':
   d={}
   j=i+1
   while j<len(lines) and lines[j]!='END:VEVENT':
    if ':' in lines[j]:
     k,v=lines[j].split(':',1);d[k]=v
    j+=1
   if 'UID' in d:result[d['UID']]=d
 return result
cal=parse(calendar); exported=parse(ics)
assert len(a['events'])==3
assert set(want)<=set(cal) and set(want)==set(exported)
for uid, (start,end,summary,room,attendee) in want.items():
 for d in [cal[uid],exported[uid]]:
  assert (d['DTSTART'],d['DTEND'],d['SUMMARY'],d['ROOM'],d['ATTENDEE'])==(start,end,summary,room,attendee)
assert all(e['confirmation_id']=='f46fe9ba84c5486b85368dacce9b7ffb' for e in a['events'])
c=sqlite3.connect('/home/user/workspace/calendar/rooms.db')
assert len(c.execute("select uid from reservations where status='CONFIRMED' and uid in ('TS-201','TS-203','TS-207')").fetchall())==3
assert len(c.execute("select uid from confirmations where uid in ('TS-201','TS-203','TS-207') and confirmation_id='f46fe9ba84c5486b85368dacce9b7ffb'").fetchall())==3
print('verified: calendar has 3 training events and both export files match; reservations/confirmations are present')
